//! The batched DFT of the round-10 lab PCS: p3's `Radix2DFTSmallBatch` for ordinary sizes, and a
//! four-step (Bailey) transform for codewords too large for memory.
//!
//! The DFT of a column is a fixed function (evaluations on the subgroup of order h generated by
//! `two_adic_generator(log h)`, natural order), so any correct algorithm yields the same field
//! elements; `dftcmp` checks the two paths against each other.
//!
//! Four-step, for h = M1 M2, n = M2 n1 + n2 and k = k1 + M1 k2:
//!   1. Y[k1, n2] = DFT_M1 over n1 of x[M2 n1 + n2]  (reads M1 chunks of B rows, stride M2 rows)
//!   2. Z[k1, n2] = Y[k1, n2] w^(n2 k1)              (w the generator of order h)
//!   3. X[k1 + M1 k2] = DFT_M2 over n2 of Z[k1, n2]  (reads M2 contiguous rows per k1)
//! Every access to the large arrays is a run of B consecutive rows, so disk-backed arrays are
//! read and written in long sequential pieces instead of the page-at-a-time random access of an
//! in-place radix-2 transform and its final bit reversal.

use p3_dft::{Radix2DFTSmallBatch, TwoAdicSubgroupDft};
use p3_field::{Field, PrimeCharacteristicRing, TwoAdicField};
use p3_matrix::Matrix;
use p3_matrix::dense::RowMajorMatrix;
use rayon::prelude::*;
use std::sync::atomic::{AtomicUsize, Ordering};

use crate::field::F;

/// Matrices of at least this many bytes take the four-step path (H9_BIGDFT_MIN; default 4 GiB).
pub static MIN_BYTES: AtomicUsize = AtomicUsize::new(4 << 30);

pub fn configure_from_env() {
    if let Ok(v) = std::env::var("H9_BIGDFT_MIN") {
        MIN_BYTES.store(v.parse().expect("H9_BIGDFT_MIN"), Ordering::Relaxed);
    }
}

#[derive(Clone, Default, Debug)]
pub struct BigDft {
    inner: Radix2DFTSmallBatch<F>,
}

impl BigDft {
    pub fn new(n: usize) -> Self {
        BigDft { inner: Radix2DFTSmallBatch::new(n) }
    }
}

impl TwoAdicSubgroupDft<F> for BigDft {
    type Evaluations = RowMajorMatrix<F>;

    fn dft_batch(&self, mat: RowMajorMatrix<F>) -> RowMajorMatrix<F> {
        let h = mat.height();
        if h >= 1 << 16 && mat.values.len() * 8 >= MIN_BYTES.load(Ordering::Relaxed) {
            four_step(&self.inner, mat)
        } else {
            self.inner.dft_batch(mat)
        }
    }
}

/// Rows per contiguous piece: about 32 KiB of field data per piece.
fn batch_rows(w: usize) -> usize {
    (4096 / w).clamp(1, 256).next_power_of_two()
}

pub fn four_step(inner: &Radix2DFTSmallBatch<F>, mut mat: RowMajorMatrix<F>) -> RowMajorMatrix<F> {
    let h = mat.height();
    let w = mat.width();
    let lg = h.trailing_zeros() as usize;
    let (l1, l2) = (lg.div_ceil(2), lg / 2);
    let (m1, m2) = (1usize << l1, 1usize << l2);
    let b = batch_rows(w).min(m2).min(m1);
    let g = F::two_adic_generator(lg);
    // Intermediate Z, row (k1 M2 + n2), w columns.
    let mut z = F::zero_vec(h * w);
    // Step 1 and 2, for B consecutive n2 at a time.
    for n2s in (0..m2).step_by(b) {
        let mut blk = vec![F::ZERO; m1 * b * w];
        blk.par_chunks_mut(b * w).enumerate().for_each(|(n1, row)| {
            let src = (m2 * n1 + n2s) * w;
            row.copy_from_slice(&mat.values[src..src + b * w]);
        });
        let y = inner.dft_batch(RowMajorMatrix::new(blk, b * w));
        let yv = y.values;
        z.par_chunks_mut(m2 * w).enumerate().for_each(|(k1, zrow)| {
            // w^(k1 n2) for n2 = n2s .. n2s + b
            let step = g.exp_u64(k1 as u64);
            let mut t = step.exp_u64(n2s as u64);
            let src = &yv[k1 * b * w..(k1 + 1) * b * w];
            let dst = &mut zrow[n2s * w..(n2s + b) * w];
            for j in 0..b {
                for c in 0..w {
                    dst[j * w + c] = src[j * w + c] * t;
                }
                t *= step;
            }
        });
    }
    // The input is no longer needed: reuse it for the output.
    let out = &mut mat.values;
    // Step 3, for B consecutive k1 at a time.
    for k1s in (0..m1).step_by(b) {
        let ys: Vec<Vec<F>> = (k1s..k1s + b)
            .map(|k1| {
                let blk = z[k1 * m2 * w..(k1 + 1) * m2 * w].to_vec();
                inner.dft_batch(RowMajorMatrix::new(blk, w)).values
            })
            .collect();
        // X[k1 + M1 k2] for the B values of k1: rows k1s .. k1s + B at each k2.
        out.par_chunks_mut(m1 * w).enumerate().for_each(|(k2, orow)| {
            for (j, y) in ys.iter().enumerate() {
                orow[(k1s + j) * w..(k1s + j + 1) * w].copy_from_slice(&y[k2 * w..(k2 + 1) * w]);
            }
        });
    }
    drop(z);
    mat
}

/// The four-step path against p3's transform on random matrices (exact equality).
pub fn selfcheck() -> Vec<(String, bool)> {
    let inner = Radix2DFTSmallBatch::<F>::new(1 << 20);
    let mut s = 0x2545_f491_4f6c_dd1du64;
    let mut next = move || {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        s
    };
    let mut v = vec![];
    for &(lg, w, zero_tail) in &[(10usize, 1usize, 0usize), (11, 3, 1), (12, 64, 1), (13, 8, 2), (16, 64, 1), (17, 5, 0), (18, 64, 1), (20, 2, 3)] {
        let h = 1usize << lg;
        let mut vals: Vec<F> = (0..h * w).map(|_| F::from_u64(next())).collect();
        for x in vals[(h >> zero_tail) * w..].iter_mut() {
            *x = F::ZERO;
        }
        let m = RowMajorMatrix::new(vals, w);
        let a = inner.dft_batch(m.clone());
        let bm = four_step(&inner, m);
        v.push((format!("four-step DFT = p3 Radix2DFTSmallBatch: height 2^{lg}, width {w}, zero tail 1 - 2^-{zero_tail}"), a.values == bm.values));
    }
    v
}
